INSERT INTO public.growth_resources (resource_type, title, author_or_host, platform, url, language, primary_pillar, secondary_pillar, difficulty, duration_hours, is_free, summary_it, evidence_url) VALUES
  ('course', 'Negoziazione e Comunicazione Efficace', 'Davide Marocco (Università di Napoli Federico II)', 'Federica Web Learning', 'https://lms.federica.eu/course/view.php?id=169', 'it', 'communication', NULL, 'base', NULL, true, 'Impari le basi della negoziazione, della gestione dei conflitti e della comunicazione interpersonale, con esercizi pratici in un serious game con personaggi virtuali.', 'https://lms.federica.eu/course/view.php?id=169'),
  ('course', 'Comunicazione efficace e gestione del conflitto', 'Elena Dell''Aquila, Davide Marocco', 'Federica Web Learning (Federica Pro - Soft Skills)', 'https://lms.federica.eu/enrol/index.php?id=974', 'it', 'communication', NULL, 'base', 6, true, 'Un corso breve per migliorare la comunicazione interpersonale e gestire i confronti difficili con tecniche assertive, provandole in simulazioni interattive.', 'https://lms.federica.eu/enrol/index.php?id=974'),
  ('course', 'Gestire il conflitto', 'Politecnico di Milano', 'POK - Polimi Open Knowledge', 'https://www.pok.polimi.it/course/view.php?id=16', 'it', 'communication', NULL, 'base', 25, true, 'Impari a preparare, strutturare e chiudere una discussione di conflitto usando ascolto empatico e feedback.', 'https://www.pok.polimi.it/course/view.php?id=16'),
  ('course', 'Improving Communication Skills', 'Maurice Schweitzer (University of Pennsylvania - Wharton)', 'Coursera', 'https://www.coursera.org/learn/wharton-communication-skills', 'en', 'communication', NULL, 'base', 10, true, 'Impari a costruire fiducia, ascoltare attivamente, scrivere messaggi persuasivi e scegliere il canale giusto per comunicare al lavoro (gratis in modalità audit).', 'https://www.coursera.org/learn/wharton-communication-skills'),
  ('course', 'Successful Negotiation: Essential Strategies and Skills', 'George Siedel (University of Michigan)', 'Coursera', 'https://www.coursera.org/learn/negotiation-skills', 'en', 'communication', NULL, 'base', NULL, true, 'Impari a preparare, condurre e chiudere una negoziazione, con strumenti come BATNA e ZOPA e una simulazione pratica (gratis in modalità audit).', 'https://www.coursera.org/learn/negotiation-skills'),
  ('course', 'Introduction to Public Speaking', 'Matt McGarrity (University of Washington)', 'Coursera', 'https://www.coursera.org/learn/public-speaking', 'en', 'communication', NULL, 'base', NULL, true, 'Impari a strutturare un discorso breve ed efficace, a gestire l''ansia e a migliorare la tua presenza quando parli in pubblico (gratis in modalità audit).', 'https://www.coursera.org/learn/public-speaking'),
  ('course', 'Effective communication in the workplace', 'The Open University', 'OpenLearn', 'https://www.open.edu/openlearn/money-business/effective-communication-the-workplace/', 'en', 'communication', NULL, 'base', 24, true, 'Un corso gratuito di otto settimane sulla comunicazione verbale, non verbale e scritta al lavoro, incluse le situazioni difficili e il lavoro da remoto.', 'https://www.open.edu/openlearn/money-business/effective-communication-the-workplace/'),
  ('course', 'Innovazione e creatività per gli imprenditori', NULL, 'Alison', 'https://alison.com/it/corso/innovazione-e-creativita-per-gli-imprenditori', 'it', 'creativity', 'drive', 'base', NULL, true, 'Impari tecniche per generare idee creative, trasformarle in soluzioni innovative e gestire i fallimenti come passi verso il successo.', 'https://alison.com/it/corso/innovazione-e-creativita-per-gli-imprenditori'),
  ('course', 'Fondamenti del Design Thinking', NULL, 'Alison', 'https://alison.com/it/corso/fondamenti-del-design-thinking', 'it', 'creativity', 'computational_power', 'avanzato', NULL, true, 'Scopri storia e fasi del design thinking e come usarlo per affrontare problemi complessi e sviluppare prodotti o servizi.', 'https://alison.com/it/corso/fondamenti-del-design-thinking'),
  ('course', 'I principi dell''innovazione nel mondo degli affari', NULL, 'Alison', 'https://alison.com/it/corso/i-principi-dell-innovazione-nel-mondo-degli-affari', 'it', 'creativity', 'knowledge', 'base', NULL, true, 'Capisci cos''è l''innovazione, le sue quattro aree (prodotti, processi, pratiche di lavoro, modello di business) e un modello in quattro passi per avviarla in azienda.', 'https://alison.com/it/corso/i-principi-dell-innovazione-nel-mondo-degli-affari'),
  ('course', 'Creative Thinking: Techniques and Tools for Success', 'Peter Childs (Imperial College London)', 'Coursera', 'https://www.coursera.org/learn/creative-thinking-techniques-and-tools-for-success', 'en', 'creativity', 'computational_power', 'base', 20, true, 'Impari diverse tecniche di pensiero creativo, come scegliere quella giusta per un problema e come combinarle nel tuo lavoro.', 'https://www.coursera.org/learn/creative-thinking-techniques-and-tools-for-success'),
  ('course', 'Creativity, Innovation, and Transformation', 'Kathryn W. Jablokow, Darrell Velegol, Jack V. Matson (Penn State)', 'Coursera', 'https://www.coursera.org/learn/creativity-innovation', 'en', 'creativity', 'drive', 'base', 20, true, 'Scopri la tua natura creativa con strumenti come l''Intelligent Fast Failure e il Mind Warping per trasformare problemi in soluzioni.', 'https://www.coursera.org/learn/creativity-innovation/home/welcome'),
  ('course', 'Making creativity and innovation happen', 'The Open University', 'OpenLearn', 'https://www.open.edu/openlearn/money-business/making-creativity-and-innovation-happen/', 'en', 'creativity', 'knowledge', 'intermedio', NULL, true, 'Esplori la creatività individuale e quella organizzativa e come cultura, leadership e struttura favoriscono l''innovazione, con attestato gratuito.', 'https://www.open.edu/openlearn/money-business/making-creativity-and-innovation-happen/'),
  ('course', 'Creative and Design Thinking: process and tools for innovation', 'Politecnico di Milano (IDEActivity Center)', 'POK - Polimi Open Knowledge', 'https://www.pok.polimi.it/course/view.php?id=107', 'en', 'creativity', 'computational_power', 'intermedio', 18, true, 'Alleni una mentalità creativa e applichi passo passo un toolbox di design thinking a una sfida reale, da solo o in gruppo.', 'https://www.pok.polimi.it/course/view.php?id=107'),
  ('book', 'La trama lucente', 'Annamaria Testa', 'Garzanti', 'https://www.garzanti.it/libri/annamaria-testa-la-trama-lucente-9788811010470/', 'it', 'creativity', 'knowledge', 'intermedio', NULL, false, 'Capisci che cos''è la creatività e come funziona, tra psicologia, neuroscienze, economia ed esempi concreti.', 'https://www.garzanti.it/libri/annamaria-testa-la-trama-lucente-9788811010470/'),
  ('book', 'Da cosa nasce cosa. Appunti per una metodologia progettuale', 'Bruno Munari', 'Laterza', 'https://www.laterza.it/scheda-libro/?isbn=9788858128770', 'it', 'creativity', 'computational_power', 'base', NULL, false, 'Impari un metodo progettuale passo passo per passare da un problema a una soluzione concreta, scoprendo che progettare non è un dono per pochi.', 'https://www.laterza.it/scheda-libro/?isbn=9788858128770'),
  ('book', 'Fantasia', 'Bruno Munari', 'Laterza', 'https://www.laterza.it/scheda-libro/?isbn=9788858128794', 'it', 'creativity', 'communication', 'base', NULL, false, 'Esplori la differenza tra fantasia, invenzione, creatività e immaginazione e come si collegano cose note per crearne di nuove.', 'https://www.laterza.it/scheda-libro/?isbn=9788858128794'),
  ('book', 'Creatività e pensiero laterale', 'Edward De Bono', 'Rizzoli Libri (BUR)', 'https://www.rizzolilibri.it/libri/creativita-e-pensiero-laterale/', 'it', 'creativity', 'computational_power', 'base', NULL, false, 'Un manuale pratico con esercizi per uscire dal pensiero logico-lineare e generare alternative con tecniche come inversione, provocazione e stimolo casuale.', 'https://www.rizzolilibri.it/libri/creativita-e-pensiero-laterale/'),
  ('book', 'Creative Confidence: Unleashing the Creative Potential Within Us All', 'Tom Kelley, David Kelley', 'Penguin Random House', 'https://www.penguinrandomhouse.com/books/226533/creative-confidence-by-tom-kelley-and-david-kelley/', 'en', 'creativity', 'drive', 'base', NULL, false, 'I fondatori di IDEO e della d.school mostrano che tutti possono essere creativi, con strategie ed esercizi per il lavoro e la vita.', 'https://www.penguinrandomhouse.com/books/226533/creative-confidence-by-tom-kelley-and-david-kelley/'),
  ('book', 'Creativity, Inc.', 'Ed Catmull, Amy Wallace', 'Penguin Random House', 'https://www.penguinrandomhouse.com/books/216369', 'en', 'creativity', 'communication', 'intermedio', NULL, false, 'Il cofondatore di Pixar racconta come costruire e proteggere una cultura creativa in un team, tra Braintrust, feedback e gestione degli errori.', 'https://www.penguinrandomhouse.com/books/216369'),
  ('book', 'Steal Like an Artist', 'Austin Kleon', 'Wikipedia', 'https://en.wikipedia.org/wiki/Steal_Like_an_Artist', 'en', 'creativity', 'drive', 'base', NULL, false, 'Dieci principi brevi e pratici per sbloccare la creatività, accettare le influenze e seguire i propri interessi.', 'https://en.wikipedia.org/wiki/Steal_Like_an_Artist'),
  ('book', 'Change by Design', 'Tim Brown', 'Apple Books', 'https://books.apple.com/us/book/id360637415', 'en', 'creativity', 'knowledge', 'intermedio', NULL, false, 'Il CEO di IDEO spiega come il design thinking trasforma le organizzazioni e stimola l''innovazione.', 'https://books.apple.com/us/book/id360637415'),
