  ('podcast', 'TED Radio Hour: Jumpstarting Creativity', 'Manoush Zomorodi (NPR)', 'NPR', 'https://www.npr.org/programs/ted-radio-hour/719553183/jumpstarting-creativity', 'en', 'creativity', 'knowledge', 'base', NULL, true, 'Un episodio in cui speaker TED spiegano come accendere e riaccendere la creatività.', 'https://www.npr.org/programs/ted-radio-hour/719553183/jumpstarting-creativity'),
  ('course', 'Imparare ad imparare', 'Politecnico di Milano', 'POK Polimi', 'https://www.pok.polimi.it/course/view.php?id=270', 'it', 'knowledge', 'drive', 'base', 25, true, 'Strategie concrete per seguire le lezioni, studiare, lavorare in gruppo e gestire il tempo, con Open Badge finale.', 'https://www.pok.polimi.it/course/view.php?id=270'),
