  ('course', 'Competenze testuali', 'CISIA / Federica Web Learning', 'Federica Web Learning', 'https://lms.federica.eu/enrol/index.php?id=978', 'it', 'knowledge', 'communication', 'base', NULL, true, 'Rafforzi la comprensione e l''analisi dei testi, base per una lettura critica e consapevole.', 'https://lms.federica.eu/enrol/index.php?id=978'),
