  ('course', 'Learning how to learn', 'The Open University', 'OpenLearn', 'https://www.open.edu/openlearn/education-development/learning-how-learn/content-section-0', 'en', 'knowledge', NULL, 'base', 6, true, 'Capisci il tuo modo di imparare e diventi uno studente riflessivo, anche con un diario di apprendimento.', 'https://www.open.edu/openlearn/education-development/learning-how-learn/content-section-0'),
  ('book', 'Come si fa una tesi di laurea', 'Umberto Eco', 'La nave di Teseo', 'https://www.lanavediteseo.eu/item/come-si-fa-una-tesi-di-laurea-edizione-best-seller/', 'it', 'knowledge', 'communication', 'base', NULL, false, 'Il classico di Eco su come scegliere un tema, fare ricerca bibliografica e organizzare il materiale: un metodo valido per ogni progetto di studio.', 'https://www.lanavediteseo.eu/item/come-si-fa-una-tesi-di-laurea-edizione-best-seller/'),
  ('book', 'L''utilità dell''inutile', 'Nuccio Ordine', 'La nave di Teseo', 'https://lanavediteseo.eu/portfolio/l-utilita-dell-inutile/', 'it', 'knowledge', 'creativity', 'intermedio', NULL, false, 'Un manifesto sul valore dei saperi "inutili" (filosofia, letteratura, scienza di base) per una mente curiosa e libera.', 'https://lanavediteseo.eu/portfolio/l-utilita-dell-inutile/'),
  ('book', 'Perché leggere i classici', 'Italo Calvino', 'Mondadori', 'https://www.mondadori.it/libri/perche-leggere-i-classici-italo-calvino/', 'it', 'knowledge', 'creativity', 'intermedio', NULL, false, 'Saggi di Calvino sul valore della lettura e della rilettura dei classici in età adulta.', 'https://www.mondadori.it/libri/perche-leggere-i-classici-italo-calvino/'),
  ('book', 'Dieci cose che ho imparato', 'Piero Angela', 'Mondadori', 'https://www.mondadori.it/libri/dieci-cose-che-ho-imparato-piero-angela/', 'it', 'knowledge', NULL, 'base', NULL, false, 'Le lezioni di una vita di divulgazione scientifica, dal cervello all''ambiente, su come pensare in modo razionale.', 'https://www.mondadori.it/libri/dieci-cose-che-ho-imparato-piero-angela/'),
  ('book', 'Make It Stick: The Science of Successful Learning', 'Peter C. Brown, Henry L. Roediger III, Mark A. McDaniel', 'Harvard University Press', 'https://www.hup.harvard.edu/books/9780674729018', 'en', 'knowledge', NULL, 'intermedio', NULL, false, 'Le strategie di apprendimento davvero efficaci secondo la ricerca cognitiva: autoverifica, ripasso distanziato e pratica alternata.', 'https://www.hup.harvard.edu/books/9780674729018'),
  ('book', 'How to Read a Book', 'Mortimer J. Adler, Charles Van Doren', 'Simon & Schuster', 'https://www.simonandschuster.com/books/How-to-Read-a-Book/Mortimer-J-Adler/9781476790152', 'en', 'knowledge', 'communication', 'intermedio', NULL, false, 'Il metodo classico per leggere in modo attivo e critico, dalla lettura ispettiva a quella analitica e sintopica.', 'https://www.simonandschuster.com/books/How-to-Read-a-Book/Mortimer-J-Adler/9781476790152'),
