  ('book', 'Ultralearning', 'Scott H. Young', 'Open Library', 'https://openlibrary.org/works/OL20846121W/Ultralearning', 'en', 'knowledge', 'drive', 'intermedio', NULL, false, 'Principi per imparare in autonomia e velocemente competenze difficili, con progetti di apprendimento intensivo.', 'https://openlibrary.org/works/OL20846121W/Ultralearning'),
  ('podcast', 'Il Mondo', 'Giulia Zoli, Claudio Rossi Marcelli (Internazionale)', 'Internazionale', 'https://www.internazionale.it/podcast/ilmondo', 'it', 'knowledge', NULL, 'base', NULL, true, 'Ogni mattina feriale due storie dal mondo scelte dalla redazione di Internazionale, per restare aggiornati oltre i confini italiani.', 'https://www.internazionale.it/podcast/ilmondo'),
  ('podcast', 'Ci vuole una scienza', 'Emanuele Menietti, Beatrice Mautino (Il Post)', 'Apple Podcasts', 'https://podcasts.apple.com/it/podcast/ci-vuole-una-scienza/id1618400511', 'it', 'knowledge', NULL, 'base', NULL, false, 'Ogni settimana le notizie scientifiche spiegate bene, e come la scienza funziona davvero come processo in evoluzione.', 'https://podcasts.apple.com/it/podcast/ci-vuole-una-scienza/id1618400511'),
  ('podcast', 'Morning', 'Il Post', 'Apple Podcasts', 'https://podcasts.apple.com/it/podcast/morning/id1584377893', 'it', 'knowledge', NULL, 'base', NULL, false, 'Una rassegna stampa quotidiana di circa 20 minuti che spiega cosa c''è sui giornali e perché certe storie diventano notizia.', 'https://podcasts.apple.com/it/podcast/morning/id1584377893'),
  ('podcast', 'ARCHIVIO WIKIRADIO 2011-2015', 'Rai Radio3', 'Apple Podcasts', 'https://podcasts.apple.com/it/podcast/archivio-wikiradio-2011-2015/id478850013', 'it', 'knowledge', NULL, 'base', NULL, true, 'Oltre mille puntate di mezz''ora che raccontano un evento storico accaduto in quel giorno, per una cultura generale solida.', 'https://podcasts.apple.com/it/podcast/archivio-wikiradio-2011-2015/id478850013'),
  ('podcast', 'The Knowledge Project', 'Shane Parrish', 'Spotify', 'https://open.spotify.com/show/1VyK52NSZHaDKeMJzT4TSM', 'en', 'knowledge', 'drive', 'intermedio', NULL, true, 'Interviste lunghe con persone di successo per assorbire modelli mentali e idee utili a pensare e decidere meglio.', 'https://open.spotify.com/show/1VyK52NSZHaDKeMJzT4TSM'),
