  ('podcast', 'Stuff You Should Know', 'Josh Clark, Chuck Bryant', 'Apple Podcasts', 'https://podcasts.apple.com/us/podcast/stuff-you-should-know/id278981407', 'en', 'knowledge', NULL, 'base', NULL, true, 'Spiegazioni chiare e divertenti su un''enorme varietà di argomenti, per allenare la curiosità e la cultura generale.', 'https://podcasts.apple.com/us/podcast/stuff-you-should-know/id278981407'),
  ('podcast', 'In Our Time', 'Misha Glenny (prima Melvyn Bragg), BBC Radio 4', 'Apple Podcasts', 'https://podcasts.apple.com/gb/podcast/in-our-time/id73330895', 'en', 'knowledge', NULL, 'intermedio', NULL, true, 'Discussioni con accademici su idee, persone e scoperte di storia, filosofia, scienza e cultura.', 'https://podcasts.apple.com/gb/podcast/in-our-time/id73330895'),
  ('course', 'Statistica', 'Roberta Siciliano (Università Federico II)', 'Federica Web Learning', 'https://lms.federica.eu/course/view.php?id=149', 'it', 'computational_power', 'knowledge', 'base', NULL, true, 'Un corso introduttivo che ti insegna le basi della statistica descrittiva e inferenziale per leggere e interpretare i dati.', 'https://lms.federica.eu/course/view.php?id=149'),
